-- Keep the displayed GitHub totals from the demonstration dataset; the trigger
-- above still increments these counts for new star rows after setup.
UPDATE repositories SET stars_count=CASE repo_id WHEN 101 THEN 1248 WHEN 102 THEN 892 WHEN 103 THEN 756 WHEN 104 THEN 634 WHEN 105 THEN 518 WHEN 106 THEN 405 WHEN 107 THEN 288 WHEN 108 THEN 126 ELSE stars_count END;
SELECT setval(pg_get_serial_sequence('users','user_id'),(SELECT MAX(user_id) FROM users));
SELECT setval(pg_get_serial_sequence('repositories','repo_id'),(SELECT MAX(repo_id) FROM repositories));
